(() => {
 'use strict';
 const data=window.KNOWLEDGE_DATA, byId=new Map(data.map(n=>[n.id,n]));
 const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icons={tree:'M12 3v18M12 5H6v5M12 9h6v5M12 15H6v5M4 10h4M16 14h4M4 20h4',checklist:'m4 6 1.5 1.5L8 4M11 6h9M4 13l1.5 1.5L8 11M11 13h9M4 20l1.5 1.5L8 18M11 20h9',box:'m12 3 9 5v9l-9 5-9-5V8l9-5Zm-9 5 9 5 9-5M12 13v9m-4.5-16.5 9 5',sprout:'M12 22v-9m0 1C4 15 2 9 3 4c6 0 10 4 9 10Zm0 3c-1-7 4-10 9-9 0 6-3 10-9 9Z',lock:'M6 10h12v11H6V10Zm3 0V6a3 3 0 0 1 6 0v4m-3 5v2',help:'M9.5 9a2.5 2.5 0 1 1 4 2c-1.5 1-1.5 1.5-1.5 3M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',search:'m21 21-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z',fit:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',terminal:'M3 4h18v16H3V4Zm4 5 3 3-3 3m6 0h4',code:'m8 5-6 7 6 7m8-14 6 7-6 7M14 3l-4 18',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',database:'M20 6c0 2-3.6 3-8 3S4 8 4 6s3.6-3 8-3 8 1 8 3Zm0 0v12c0 2-3.6 3-8 3s-8-1-8-3V6m0 6c0 2 3.6 3 8 3s8-1 8-3',branch:'M6 8v8m12-8v2c0 4-12 0-12 6M9 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm12 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM9 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',flask:'M9 3h6M10 3v7L4 20v1h16v-1l-6-10V3M7 15h10',link:'m10 13 4-4m-6 6-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 3 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',activity:'M2 12h5l3-9 4 18 3-9h5',workflow:'M3 3h6v6H3V3Zm12 12h6v6h-6v-6ZM6 9v9h9M9 6h9v9',rocket:'M14 5c3-3 7-2 7-2s1 4-2 7l-8 8-5-5 8-8ZM8 11H3l3-5h6m1 10v5l5-3v-6M4 16l-2 6 6-2M15 7l2 2',route:'M6 3a3 3 0 1 1 0 6 3 3 0 0 1 0-6Zm12 12a3 3 0 1 1 0 6 3 3 0 0 1 0-6ZM6 9v7h7M11 3h7v7m-3-3 3 3 3-3',arrow:'M4 12h16m-6-6 6 6-6 6'};
 const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
 $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
 const statuses={mastered:'已掌握',learning:'学习中',review:'待巩固',explore:'待探索'}, colors={mastered:'green',learning:'amber',review:'coral',explore:'gray'};
 let persisted={};try{persisted=JSON.parse(localStorage.getItem('knowledge-os-demo-v1')||'{}')||{}}catch{}
 const state={selected:byId.has(persisted.selected)?persisted.selected:'cicd',tab:'overview',view:'tree',filter:'all',query:'',path:false,tasks:persisted.tasks&&typeof persisted.tasks==='object'?persisted.tasks:{},statuses:persisted.statuses&&typeof persisted.statuses==='object'?persisted.statuses:{},scale:1,x:0,y:0};
 let toastTimer;
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
 function save(){try{localStorage.setItem('knowledge-os-demo-v1',JSON.stringify({selected:state.selected,tasks:state.tasks,statuses:state.statuses}));return true}catch{toast('浏览器未允许保存；当前会话仍可继续探索');return false}}
 function status(n){return statuses[state.statuses[n.id]]?state.statuses[n.id]:n.status}
 function done(n,i){return typeof state.tasks[n.id+'-'+i]==='boolean'?state.tasks[n.id+'-'+i]:(n.status==='mastered'||(n.id==='api'&&i===0))}
 function doneCount(n){return n.tasks.filter((_,i)=>done(n,i)).length}
 function progress(n){return Math.round(doneCount(n)/n.tasks.length*100)}
 function ancestors(id,set=new Set()){const n=byId.get(id);if(!n||set.has(id))return set;set.add(id);n.prereqs.forEach(p=>ancestors(p,set));return set}
 function matches(n){return(state.filter==='all'||status(n)===state.filter)&&(!state.query||[n.title,n.en,n.tag,n.summary].some(s=>s.toLowerCase().includes(state.query)))}
 function renderGraph(){
  const ancestry=ancestors(state.selected), selected=byId.get(state.selected);
  $('#nodes').innerHTML=data.map(n=>{const s=status(n),match=matches(n);return `<button class="node status-${s} ${n.layer===3?'project':''} ${n.id===state.selected?'selected':''} ${state.path&&!ancestry.has(n.id)?'dimmed':''} ${state.path&&ancestry.has(n.id)&&n.id!==state.selected?'path-node':''} ${!match?'hidden-by-filter':''}" style="left:${n.x}px;top:${n.y}px" data-node="${n.id}" data-testid="node-${n.id}" aria-label="${esc(n.title)} · ${statuses[s]}" aria-pressed="${n.id===state.selected}" ${!match?'tabindex="-1" aria-disabled="true"':''}><span class="node-port in"></span><span class="node-header"><span class="node-icon">${icon(n.icon)}</span><span><span class="node-title">${esc(n.title)}</span><span class="node-en" style="display:block">${esc(n.en)}</span></span></span><span class="node-footer"><i class="small-dot ${colors[s]}"></i>${statuses[s]}<span class="node-progress"><span style="width:${progress(n)}%"></span></span></span><span class="node-port out"></span></button>`}).join('');
  $('#connections').innerHTML='<defs><marker id="arrowhead" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="4" markerHeight="4" orient="auto"><path d="M1 1L6 4 1 7" fill="none" stroke="#a7b998" stroke-width="1.3"/></marker></defs>'+data.flatMap(n=>n.prereqs.map(id=>{const p=byId.get(id),x1=p.x+87,y1=p.y-3,x2=n.x+87,y2=n.y+(n.layer===3?99:94);let d;if(p.y===n.y){const start=p.x+174,end=n.x,mid=(start+end)/2;d=`M${start} ${p.y+45} C${mid} ${p.y+45},${mid} ${n.y+45},${end} ${n.y+45}`}else{const mid=(y1+y2)/2;d=`M${x1} ${y1} C${x1} ${mid},${x2} ${mid},${x2} ${y2}`};const active=state.path&&ancestry.has(id)&&ancestry.has(n.id);return `<path class="connection ${active?'active':''} ${state.path&&!active?'dimmed':''} ${!state.path&&(n.id===selected.id||id===selected.id)?'related':''} ${!matches(n)||!matches(p)?'dimmed':''}" d="${d}" data-from="${id}" data-to="${n.id}" marker-end="url(#arrowhead)"/>`})).join('');
  const count=data.filter(matches).length;$('#empty-search').hidden=count>0;$('#search-count').textContent=count+' 个匹配';
  const mastered=data.filter(n=>status(n)==='mastered').length;$('#map-summary').textContent=`${data.length} NODES / ${mastered} MASTERED`;
 }
 function taskMarkup(n,i){return `<label class="task-check ${done(n,i)?'completed':''}"><input type="checkbox" data-task="${n.id}" data-index="${i}" ${done(n,i)?'checked':''}><span>${esc(n.tasks[i])}</span></label>`}
 function renderDetail(){
  const n=byId.get(state.selected),s=status(n),tabs=[['overview','知识说明'],['tasks','学习任务'],['evidence','项目证据'],['mistakes','常错点']];
  let content='';
  if(state.tab==='overview')content=`<p class="detail-summary">${esc(n.summary)}</p><h3 class="section-title"><span></span>核心概念</h3>${n.concepts.map(c=>`<article class="concept"><h4>${esc(c[0])}</h4><p>${esc(c[1])}</p></article>`).join('')}<div class="prereq-section"><h3 class="section-title"><span></span>前置能力</h3>${n.prereqs.length?`<div class="prereq-buttons">${n.prereqs.map(id=>`<button class="prereq-chip" data-node="${id}">${esc(byId.get(id).title)} ↗</button>`).join('')}</div>`:'<p class="no-prereqs">这是基础起点，可以从这里开始学习。</p>'}</div>`;
  if(state.tab==='tasks')content=`<h3 class="section-title"><span></span>把理解变成一次行动</h3><p class="task-intro">完成后勾选，进度会保存在当前浏览器。完成任务不自动代表掌握能力。</p>${n.tasks.map((_,i)=>taskMarkup(n,i)).join('')}<p class="task-progress">${doneCount(n)} / ${n.tasks.length} TASKS COMPLETED</p>`;
  if(state.tab==='evidence')content=`<div class="evidence-banner">${icon('box')}虚构示例 · 非真实文件或验收记录</div><h3 class="section-title"><span></span>能力如何被证明</h3>${n.evidence.map((e,i)=>`<details class="evidence-card" ${i===0?'open':''}><summary>${esc(e[0])}</summary><div class="evidence-path">${esc(e[1])}</div><p>${esc(e[2])}</p></details>`).join('')}<p class="task-intro">证据将实践结果关联到能力节点。这里的路径仅用于演示，不会访问外部文件。</p>`;
  if(state.tab==='mistakes')content=`<h3 class="section-title"><span></span>把踩过的坑留下来</h3>${n.mistakes.map((m,i)=>`<article class="mistake"><span class="mistake-number">WATCH OUT / 0${i+1}</span><strong>${esc(m[0])}</strong><p>${esc(m[1])}</p></article>`).join('')}`;
  $('#detail-panel').innerHTML=`<div class="detail-top"><div class="detail-kicker"><span>NODE / ${String(data.indexOf(n)+1).padStart(2,'0')}</span><span>${n.tag}</span><button class="icon-button mobile-detail-close" aria-label="收起节点详情" style="display:none">×</button></div><div class="big-icon">${icon(n.icon)}</div><h2>${esc(n.title)}</h2><span class="detail-en">${esc(n.en)}</span><div class="detail-status-row"><select class="status-select" id="node-status" aria-label="学习状态">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${k===s?'selected':''}>${v}</option>`).join('')}</select><span class="progress-label">TASKS ${doneCount(n)}/${n.tasks.length}</span></div><div class="progress-track"><span style="width:${progress(n)}%"></span></div></div><div class="detail-tabs" role="tablist" aria-label="节点内容">${tabs.map(([id,label])=>`<button class="detail-tab ${state.tab===id?'active':''}" role="tab" aria-selected="${state.tab===id}" id="tab-${id}" aria-controls="node-tab-content" data-tab="${id}">${label}</button>`).join('')}</div><div class="detail-content" id="node-tab-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${content}</div><div class="detail-bottom"><button class="path-button ${state.path?'active':''}" id="path-button" aria-pressed="${state.path}">${icon('route')}${state.path?'退出路径高亮':'高亮前置路径'}<span>↗</span></button><div class="detail-footnote"><span>虚构示例 · 可自由探索</span><span>LOCAL PROGRESS</span></div></div>`;
 }
 function renderTasks(){const nodes=data.filter(n=>status(n)!=='mastered');const total=nodes.reduce((a,n)=>a+n.tasks.length,0),doneTotal=nodes.reduce((a,n)=>a+doneCount(n),0);$('#tasks-view').innerHTML=`<div class="view-head"><h2>下一步，做点什么。</h2><span class="mono">${doneTotal} / ${total} COMPLETED</span></div><p class="view-intro">每个小任务，都连向一个具体能力。进度仅保存在当前浏览器。</p>${nodes.map(n=>`<section class="task-group"><div class="task-group-title"><button data-node="${n.id}">${esc(n.title)} ↗</button><span>${doneCount(n)}/${n.tasks.length}</span></div>${n.tasks.map((_,i)=>taskMarkup(n,i)).join('')}</section>`).join('')||'<p class="view-intro">所有能力已标记为掌握。可以返回能力树选择下一项练习。</p>'}`;}
 function renderProjects(){const projects=data.filter(n=>n.layer===3);$('#projects-view').innerHTML=`<div class="view-head"><h2>做过的事，就是证据。</h2><span class="mono">03 SAMPLE PROJECTS</span></div><p class="view-intro">这里用虚构项目演示能力与实践的关系。没有接入仓库或外部账号。</p>${projects.map((n,i)=>`<article class="project-card"><div class="project-card-header"><h3>${esc(n.title)}</h3><span class="mono">PROJECT / 0${i+1}</span></div><p>${esc(n.summary)}</p><div class="project-skills">${[...ancestors(n.id)].filter(id=>id!==n.id).map(id=>`<button data-node="${id}">${esc(byId.get(id).title)}</button>`).join('')}</div><div class="project-card-bottom"><span>${n.evidence.length} 份示例记录 · ${statuses[status(n)]}</span><button data-project="${n.id}">展开证据 ↗</button></div></article>`).join('')}`;}
 function updateCounts(){$('#task-count').textContent=data.reduce((a,n)=>a+n.tasks.filter((_,i)=>!done(n,i)).length,0)}
 function selectNode(id,tab='overview'){if(!byId.has(id))return;state.selected=id;state.tab=tab;save();renderGraph();renderDetail();if(matchMedia('(max-width:760px)').matches){$('#detail-panel').classList.add('mobile-open');$('#detail-panel').scrollIntoView({behavior:'smooth',block:'start'})}}
 const viewInfo={tree:['能力树','让知识，长成能力。','从基础出发，在项目里生根。探索你的每一步如何相连。'],tasks:['学习清单','让下一步，具体一点。','从一个小任务开始，把理解变成可重复的行动。'],projects:['项目证据','能力，要有实践作答。','把做过的事连回知识，留下可以复查的成长记录。']};
 function setView(view){if(!viewInfo[view])return;state.view=view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));for(const v of ['tree','tasks','projects'])$('#'+v+'-view').hidden=v!==view;$('#page-crumb').textContent=viewInfo[view][0];$('#page-title').textContent=viewInfo[view][1];$('#page-description').textContent=viewInfo[view][2];if(view==='tasks')renderTasks();if(view==='projects')renderProjects();if(view==='tree')requestAnimationFrame(fit);}
 function clampPan(){const v=$('#graph-viewport');const w=1000*state.scale,h=710*state.scale;state.x=Math.max(Math.min(50,v.clientWidth-w-50),Math.min(v.clientWidth-50,state.x));state.y=Math.max(Math.min(40,v.clientHeight-h-40),Math.min(v.clientHeight-40,state.y));}
 function transform(){clampPan();$('#graph-world').style.transform=`translate(${state.x}px,${state.y}px) scale(${state.scale})`;$('#zoom-value').textContent=Math.round(state.scale*100)+'%';$('#zoom-out').disabled=state.scale<=.4;$('#zoom-in').disabled=state.scale>=1.6;}
 function fit(){const v=$('#graph-viewport');if(!v.clientWidth)return;state.scale=Math.min((v.clientWidth-20)/1000,(v.clientHeight-10)/710,1.15);if(matchMedia('(max-width:760px)').matches)state.scale=Math.max(.68,state.scale);state.scale=Math.max(.4,state.scale);state.x=(v.clientWidth-1000*state.scale)/2;state.y=(v.clientHeight-710*state.scale)/2;transform()}
 function zoom(delta,cx,cy){const v=$('#graph-viewport');cx??=v.clientWidth/2;cy??=v.clientHeight/2;const next=Math.max(.4,Math.min(1.6,state.scale+delta)),ratio=next/state.scale;state.x=cx-(cx-state.x)*ratio;state.y=cy-(cy-state.y)*ratio;state.scale=next;transform()}
 function setFilter(filter){state.filter=filter;state.path=false;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));renderGraph();renderDetail()}
 document.addEventListener('click',e=>{
  const node=e.target.closest('[data-node]');if(node){if(node.getAttribute('aria-disabled')==='true')return;if(state.view!=='tree'&&node.classList.contains('recent-item'))setView('tree');selectNode(node.dataset.node);return}
  const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderDetail();$('#tab-'+state.tab).focus();return}
  const view=e.target.closest('[data-view]');if(view){setView(view.dataset.view);return}
  const filter=e.target.closest('[data-filter]');if(filter){setFilter(filter.dataset.filter);return}
  const project=e.target.closest('[data-project]');if(project){selectNode(project.dataset.project,'evidence');return}
  if(e.target.closest('#path-button')){if(state.view!=='tree')setView('tree');state.path=!state.path;if(state.path){state.filter='all';state.query='';$('#node-search').value='';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'))}renderGraph();renderDetail();toast(state.path?'已高亮当前节点与全部前置能力':'已恢复完整能力地图');if(matchMedia('(max-width:760px)').matches)$('#tree-view').scrollIntoView({behavior:'smooth'});return}
  if(e.target.closest('.mobile-detail-close'))$('#detail-panel').classList.remove('mobile-open');
 });
 document.addEventListener('change',e=>{if(e.target.matches('[data-task]')){const n=byId.get(e.target.dataset.task),i=Number(e.target.dataset.index);state.tasks[n.id+'-'+i]=e.target.checked;const saved=save();renderGraph();renderDetail();renderTasks();updateCounts();if(saved)toast(e.target.checked?'已完成一个小目标 · 进度已保存':'已取消完成 · 进度已保存');}if(e.target.id==='node-status'){state.statuses[state.selected]=e.target.value;save();renderGraph();renderDetail();renderTasks();renderProjects();toast('学习状态已更新')}});
 $('#zoom-in').addEventListener('click',()=>zoom(.1));$('#zoom-out').addEventListener('click',()=>zoom(-.1));$('#fit').addEventListener('click',fit);
 const viewport=$('#graph-viewport');let drag=null;
 viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;drag={x:e.clientX,y:e.clientY,baseX:state.x,baseY:state.y};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')});
 viewport.addEventListener('pointermove',e=>{if(!drag)return;state.x=drag.baseX+e.clientX-drag.x;state.y=drag.baseY+e.clientY-drag.y;transform()});
 const stopDrag=()=>{drag=null;viewport.classList.remove('dragging')};viewport.addEventListener('pointerup',stopDrag);viewport.addEventListener('pointercancel',stopDrag);
 viewport.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();const r=viewport.getBoundingClientRect();zoom(e.deltaY>0?-.05:.05,e.clientX-r.left,e.clientY-r.top)}},{passive:false});
 viewport.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(e.key==='+'||e.key==='='){e.preventDefault();zoom(.1)}else if(e.key==='-'){e.preventDefault();zoom(-.1)}else if(e.key==='Home'){e.preventDefault();fit()}});
 $('#search-toggle').addEventListener('click',()=>{$('#search-box').hidden=!$('#search-box').hidden;if(!$('#search-box').hidden)$('#node-search').focus()});
 $('#search-close').addEventListener('click',()=>{state.query='';$('#node-search').value='';$('#search-box').hidden=true;renderGraph()});
 $('#node-search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();state.path=false;renderGraph();renderDetail()});
 $('#clear-filters').addEventListener('click',()=>{state.query='';$('#node-search').value='';setFilter('all')});
 $('#next-step-button').addEventListener('click',()=>selectNode('cicd','tasks'));
 $('.brand').addEventListener('click',e=>{e.preventDefault();setView('tree');setFilter('all');state.query='';$('#node-search').value='';renderGraph();fit()});
 function closeGuide(){$('#guide-modal').hidden=true;$('#guide-button').focus()}
 $('#guide-button').addEventListener('click',()=>{$('#guide-modal').hidden=false;$('#guide-close').focus()});$('#guide-close').addEventListener('click',closeGuide);$('#guide-start').addEventListener('click',closeGuide);$('#guide-modal').addEventListener('click',e=>{if(e.target.id==='guide-modal')closeGuide()});
 document.addEventListener('keydown',e=>{if(!$('#guide-modal').hidden){if(e.key==='Escape')closeGuide();if(e.key==='Tab'){const focusable=[$('#guide-close'),$('#guide-start')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable[1].focus()}else if(!e.shiftKey&&document.activeElement===focusable[1]){e.preventDefault();focusable[0].focus()}}}else if(e.key==='Escape'&&!$('#search-box').hidden){$('#search-close').click();$('#search-toggle').focus()}});
 renderGraph();renderDetail();renderTasks();renderProjects();updateCounts();requestAnimationFrame(fit);
 new ResizeObserver(()=>{if(state.view==='tree')fit()}).observe(viewport);
})();
